package com.mirutina.diaria;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.net.Uri;import android.graphics.Color;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {JSONArray week;LinearLayout page;Handler handler=new Handler();public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=getPackageManager().PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},11);try{week=Scheduler.load(this);}catch(Exception e){}Scheduler.schedule(this);render();handler.postDelayed(new Runnable(){public void run(){render();handler.postDelayed(this,60000);}},60000);}TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(25,35,60));t.setPadding(18,12,18,12);return t;}int minutes(String s){String[] p=s.split(":");return Integer.parseInt(p[0])*60+Integer.parseInt(p[1]);}void render(){ScrollView sc=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(1);page.setPadding(14,20,14,20);page.setBackgroundColor(Color.rgb(244,247,253));sc.addView(page);setContentView(sc);page.addView(label("MI RUTINA DIARIA",26));Calendar now=Calendar.getInstance();int d=(now.get(Calendar.DAY_OF_WEEK)+5)%7;String[] names={"Lunes","Martes","Miércoles","Jueves","Viernes","Sábado","Domingo"};int mins=now.get(Calendar.HOUR_OF_DAY)*60+now.get(Calendar.MINUTE);page.addView(label(names[d]+" • "+String.format(Locale.getDefault(),"%02d:%02d",now.get(Calendar.HOUR_OF_DAY),now.get(Calendar.MINUTE)),20));try{JSONArray entries=week.getJSONArray(d);String current="Tiempo libre",next="No hay más actividades hoy";for(int i=0;i<entries.length();i++){JSONArray a=entries.getJSONArray(i);int st=minutes(a.getString(0)),end=minutes(a.getString(1));if(mins>=st&&mins<end)current=a.getString(2)+" (hasta "+a.getString(1)+")";if(st>mins){next=a.getString(0)+" • "+a.getString(2);break;}}page.addView(label("AHORA: "+current,20));page.addView(label("SIGUIENTE: "+next,17));}catch(Exception ignored){}Button alarms=new Button(this);alarms.setText("Permitir alarmas exactas");alarms.setOnClickListener(v->{if(Build.VERSION.SDK_INT>=31)startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));else Scheduler.schedule(this);});page.addView(alarms);page.addView(label("HORARIO DE HOY",20));try{JSONArray entries=week.getJSONArray(d);for(int k=0;k<entries.length();k++){JSONArray a=entries.getJSONArray(k);String key=d+"-"+k+"-"+now.get(Calendar.DAY_OF_YEAR);CheckBox cb=new CheckBox(this);cb.setText(a.getString(0)+"–"+a.getString(1)+"  "+a.getString(2));cb.setTextSize(15);cb.setPadding(8,8,8,8);cb.setChecked(getPreferences(0).getBoolean(key,false));cb.setOnCheckedChangeListener((v,checked)->getPreferences(0).edit().putBoolean(key,checked).apply());page.addView(cb);}}catch(Exception ignored){}page.addView(label("Avisos 10 minutos antes. Activa notificaciones y alarmas exactas.",13));}protected void onResume(){super.onResume();Scheduler.schedule(this);}}
